// Detector corpus: runs extractPdf + detectFields over fixtures/agreements/*.pdf and scores
// the proposals against <name>.expected.json (generated by scripts/make-fixtures.mjs).
//
//   node scripts/make-fixtures.mjs && npx vitest run test/detect.test.ts
//
// Match = same page, same type, same role, and the detected box centre within TOL_X / TOL_Y
// of the expected centre. Expected entries may list acceptTypes / acceptRoles for genuinely
// ambiguous fields. DOCX fixtures have no coordinates; they are scored by page/type/role once
// a converted <name>.pdf exists next to them.

import fs from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { extractPdf } from "@/lib/pdf/extract";
import { detectFields } from "@/lib/detect";
import type { Field, FieldType, Role } from "@/lib/fields";

// FIXTURE_DIR=fixtures/holdout scores the held-out corpus (scripts/make-holdout.mjs) instead.
const DIR = path.resolve(__dirname, "..", process.env.FIXTURE_DIR ?? path.join("fixtures", "agreements"));
const TOL_X = 40;
const TOL_Y = 25;
// Regression floor per corpus (tuning set is near-perfect; held-out sets are the honest measure).
const FLOORS: Record<string, number> = { agreements: 0.93, holdout: 0.85, final: 0.88 };
const MIN_RECALL = FLOORS[path.basename(DIR)] ?? 0;

type Exp = {
  page?: number;
  type: FieldType;
  role: Role;
  x?: number;
  y?: number;
  w?: number;
  h?: number;
  note?: string;
  acceptTypes?: FieldType[];
  acceptRoles?: Role[];
};
type ExpectedFile = { firmName?: string; description?: string; source?: string; fields: Exp[]; warnings?: string[] };

type Issue = { kind: "FN" | "FP" | "ROLE" | "TYPE" | "TYPE+ROLE" | "WARN" | "ERROR"; text: string };
type Score = {
  fixture: string;
  expected: number;
  detected: number;
  tp: number;
  fp: number;
  fn: number;
  wrongRole: number;
  wrongType: number;
  warnOk: boolean;
  issues: Issue[];
  perType: Map<string, { tp: number; fp: number; fn: number }>;
};

const hasBox = (e: Exp) => e.x !== undefined && e.y !== undefined && e.w !== undefined && e.h !== undefined;
const cx = (b: { x: number; w: number }) => b.x + b.w / 2;
const cy = (b: { y: number; h: number }) => b.y + b.h / 2;
const typeOk = (d: Field, e: Exp) => d.type === e.type || !!e.acceptTypes?.includes(d.type);
const roleOk = (d: Field, e: Exp) => d.role === e.role || !!e.acceptRoles?.includes(d.role);
const pageOk = (d: Field, e: Exp) => e.page === undefined || e.page === d.page;

function nearness(d: Field, e: Exp): number | null {
  if (!pageOk(d, e)) return null;
  if (!hasBox(e)) return 0; // docx: position unknown
  const dx = Math.abs(cx(d) - cx(e as Required<Exp>));
  const dy = Math.abs(cy(d) - cy(e as Required<Exp>));
  if (dx > TOL_X || dy > TOL_Y) return null;
  return dx / TOL_X + dy / TOL_Y;
}

function greedy(dets: Field[], exps: Exp[], ok: (d: Field, e: Exp) => boolean, usedD: Set<number>, usedE: Set<number>) {
  const pairs: { di: number; ei: number; dist: number }[] = [];
  dets.forEach((d, di) => {
    if (usedD.has(di)) return;
    exps.forEach((e, ei) => {
      if (usedE.has(ei) || !ok(d, e)) return;
      const n = nearness(d, e);
      if (n !== null) pairs.push({ di, ei, dist: n });
    });
  });
  pairs.sort((a, b) => a.dist - b.dist);
  const out: { di: number; ei: number }[] = [];
  for (const p of pairs) {
    if (usedD.has(p.di) || usedE.has(p.ei)) continue;
    usedD.add(p.di);
    usedE.add(p.ei);
    out.push(p);
  }
  return out;
}

const fmtE = (e: Exp) =>
  `p${e.page ?? "?"} ${e.type}/${e.role}${e.note ? ` "${e.note}"` : ""}${hasBox(e) ? ` @(${Math.round(e.x!)},${Math.round(e.y!)} ${Math.round(e.w!)}x${Math.round(e.h!)})` : ""}`;
const fmtD = (d: Field) =>
  `p${d.page} ${d.type}/${d.role} "${d.label}" @(${Math.round(d.x)},${Math.round(d.y)} ${Math.round(d.w)}x${Math.round(d.h)}) conf=${d.confidence ?? "-"} [${d.reason ?? ""}]`;

function score(fixture: string, exp: ExpectedFile, dets: Field[], warnings: string[]): Score {
  const exps = exp.fields;
  const usedD = new Set<number>();
  const usedE = new Set<number>();
  const tps = greedy(dets, exps, (d, e) => typeOk(d, e) && roleOk(d, e), usedD, usedE);
  // near misses: right place, wrong type and/or role (still counted as FP + FN)
  const near = greedy(dets, exps, () => true, new Set(usedD), new Set(usedE));
  const issues: Issue[] = [];
  let wrongRole = 0;
  let wrongType = 0;
  const nearD = new Set<number>();
  const nearE = new Set<number>();
  for (const { di, ei } of near) {
    const d = dets[di];
    const e = exps[ei];
    const t = typeOk(d, e);
    const r = roleOk(d, e);
    nearD.add(di);
    nearE.add(ei);
    if (!r) wrongRole++;
    if (!t) wrongType++;
    const kind = !t && !r ? "TYPE+ROLE" : !t ? "TYPE" : "ROLE";
    issues.push({ kind, text: `expected ${fmtE(e)}  got ${fmtD(d)}` });
  }
  exps.forEach((e, ei) => {
    if (!usedE.has(ei) && !nearE.has(ei)) issues.push({ kind: "FN", text: fmtE(e) });
  });
  dets.forEach((d, di) => {
    if (!usedD.has(di) && !nearD.has(di)) issues.push({ kind: "FP", text: fmtD(d) });
  });
  const wantWarn = exp.warnings ?? [];
  const missingWarn = wantWarn.filter((k) => !warnings.some((w) => w.toLowerCase().includes(k.toLowerCase())));
  if (missingWarn.length) issues.push({ kind: "WARN", text: `missing warning(s): ${missingWarn.map((k) => `"${k}"`).join(", ")}` });

  const perType = new Map<string, { tp: number; fp: number; fn: number }>();
  const bump = (k: string, f: "tp" | "fp" | "fn") => {
    const v = perType.get(k) ?? { tp: 0, fp: 0, fn: 0 };
    v[f]++;
    perType.set(k, v);
  };
  for (const { ei } of tps) bump(`${exps[ei].type}/${exps[ei].role}`, "tp");
  exps.forEach((e, ei) => !usedE.has(ei) && bump(`${e.type}/${e.role}`, "fn"));
  dets.forEach((d, di) => !usedD.has(di) && bump(`${d.type}/${d.role}`, "fp"));

  return {
    fixture,
    expected: exps.length,
    detected: dets.length,
    tp: tps.length,
    fp: dets.length - tps.length,
    fn: exps.length - tps.length,
    wrongRole,
    wrongType,
    warnOk: missingWarn.length === 0,
    issues,
    perType,
  };
}

const ratio = (a: number, b: number) => (b === 0 ? "-" : (a / b).toFixed(2));

describe("field detector corpus", () => {
  it("scores every fixture and prints a report", async () => {
    expect(fs.existsSync(DIR), `missing ${DIR}; run node scripts/make-fixtures.mjs`).toBe(true);
    const names = fs
      .readdirSync(DIR)
      .filter((f) => f.endsWith(".expected.json"))
      .map((f) => f.replace(/\.expected\.json$/, ""))
      .sort();
    expect(names.length).toBeGreaterThan(0);

    const scores: Score[] = [];
    const skipped: string[] = [];
    const detail: string[] = [];
    for (const name of names) {
      const exp = JSON.parse(fs.readFileSync(path.join(DIR, `${name}.expected.json`), "utf8")) as ExpectedFile;
      const pdfPath = path.join(DIR, `${name}.pdf`);
      if (!fs.existsSync(pdfPath)) {
        skipped.push(`${name} (${exp.source === "docx" ? "docx not converted yet" : "no pdf"})`);
        continue;
      }
      try {
        const ex = await extractPdf(new Uint8Array(fs.readFileSync(pdfPath)));
        const det = detectFields(ex, { firmName: exp.firmName });
        const s = score(name, exp, det.fields, det.warnings);
        scores.push(s);
        if (s.issues.length) {
          detail.push(`\n── ${name}  (firm: ${exp.firmName ?? "-"})`);
          if (exp.description) detail.push(`   ${exp.description}`);
          for (const i of s.issues.sort((a, b) => a.kind.localeCompare(b.kind))) detail.push(`   ${i.kind.padEnd(9)} ${i.text}`);
          detail.push(`   warnings: ${det.warnings.length ? det.warnings.map((w) => `"${w}"`).join(" | ") : "(none)"}`);
          detail.push(`   defined terms: firm=[${det.defined.firm.join(", ")}] client=[${det.defined.client.join(", ")}]`);
        }
      } catch (err) {
        const s: Score = { fixture: name, expected: exp.fields.length, detected: 0, tp: 0, fp: 0, fn: exp.fields.length, wrongRole: 0, wrongType: 0, warnOk: false, issues: [], perType: new Map() };
        s.issues.push({ kind: "ERROR", text: String((err as Error)?.stack ?? err) });
        scores.push(s);
        detail.push(`\n── ${name}\n   ERROR ${String((err as Error)?.message ?? err)}`);
      }
    }

    const tot = scores.reduce((a, s) => ({ tp: a.tp + s.tp, fp: a.fp + s.fp, fn: a.fn + s.fn }), { tp: 0, fp: 0, fn: 0 });
    const precision = tot.tp + tot.fp ? tot.tp / (tot.tp + tot.fp) : 1;
    const recall = tot.tp + tot.fn ? tot.tp / (tot.tp + tot.fn) : 1;

    console.log(`\nDETECTOR CORPUS  (match: same page+type+role, centre within ${TOL_X}pt x / ${TOL_Y}pt y)`);
    console.table(
      scores.map((s) => ({
        fixture: s.fixture,
        exp: s.expected,
        det: s.detected,
        TP: s.tp,
        FP: s.fp,
        FN: s.fn,
        "wrong role": s.wrongRole,
        "wrong type": s.wrongType,
        P: ratio(s.tp, s.tp + s.fp),
        R: ratio(s.tp, s.tp + s.fn),
        warnings: s.warnOk ? "ok" : "MISSING",
      })),
    );
    const byType = new Map<string, { tp: number; fp: number; fn: number }>();
    for (const s of scores)
      for (const [k, v] of s.perType) {
        const t = byType.get(k) ?? { tp: 0, fp: 0, fn: 0 };
        t.tp += v.tp;
        t.fp += v.fp;
        t.fn += v.fn;
        byType.set(k, t);
      }
    console.log("BY TYPE/ROLE (FP keyed by the detected type/role, FN by the expected one)");
    console.table(
      [...byType]
        .sort((a, b) => a[0].localeCompare(b[0]))
        .map(([k, v]) => ({ "type/role": k, TP: v.tp, FP: v.fp, FN: v.fn, P: ratio(v.tp, v.tp + v.fp), R: ratio(v.tp, v.tp + v.fn) })),
    );
    console.log(
      `OVERALL  TP=${tot.tp} FP=${tot.fp} FN=${tot.fn}  precision=${precision.toFixed(3)}  recall=${recall.toFixed(3)}  ` +
        `wrong-role=${scores.reduce((a, s) => a + s.wrongRole, 0)} wrong-type=${scores.reduce((a, s) => a + s.wrongType, 0)}  ` +
        `warnings ok ${scores.filter((s) => s.warnOk).length}/${scores.length}`,
    );
    if (skipped.length) console.log(`skipped: ${skipped.join("; ")}`);
    if (detail.length) console.log("\nDETAILS (ROLE/TYPE = right box, wrong label; counted as 1 FP + 1 FN)" + detail.join("\n"));

    expect(scores.filter((s) => s.issues.some((i) => i.kind === "ERROR")).map((s) => s.fixture)).toEqual([]);
    expect(recall).toBeGreaterThanOrEqual(MIN_RECALL);
  });
});
